css:
.p09-e { --frame-w: var(--w2); }
.p09-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p09-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) 0; }
.p09-err .banner { width: 100%; }
.p09-top { display: grid; gap: var(--s-2); }
.p09-top:empty { display: none; }
.p09-btnwrap { position: relative; display: inline-block; }
.p09-tip { position: absolute; z-index: 30; width: max-content; max-width: 17.5rem; }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p09-expl { flex: 1; display: grid; gap: var(--s-1); max-width: var(--measure); }

.p09-wrap { max-width: 56rem; margin-inline: auto; display: grid; gap: var(--s-4); }
.p09-list { display: grid; }
.p09-hz { display: grid; gap: var(--s-2); align-content: start; }
.p09-hz + .p09-hz { margin-top: var(--s-4); padding-top: var(--s-4); border-top: var(--w1) solid var(--rule); }
.p09-hz__head { display: grid; }
.p09-empty { color: var(--text-2); padding: var(--s-1) 0; }
.p09-add { position: relative; display: flex; flex-wrap: wrap; align-items: flex-start; gap: var(--s-2); }
.p09-add .banner { flex: 1 1 100%; }
.p09-val { display: grid; grid-template-columns: 3.25rem 2rem; align-items: center; justify-content: end; column-gap: var(--s-1); }
.p09-date { text-align: end; }
.p09-tbtn { display: flex; align-items: center; width: 100%; min-height: var(--hit); padding: 0; border: 0; background: none; text-align: start; cursor: pointer; }
.p09-list .check { min-width: var(--hit); justify-content: center; }
.p09-list .check input:disabled:checked + .check__box { background-color: var(--line); border-color: var(--line); }
.p09-list .ibtn[aria-disabled="true"] { border-color: transparent; }
.p09-hov { position: relative; display: inline-grid; }
.p09-slot { width: var(--hit); height: var(--hit); flex: none; }
.p09-tip-r { right: 0; top: calc(100% + var(--s-1)); }
.p09-tip-l { left: 0; top: calc(100% + var(--s-1)); }
.p09-note { padding: var(--s-2) var(--s-3); font-size: var(--fs-small); line-height: var(--lh-small); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p09-list .rec { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "lead body body" "lead value actions"; }
  .p09-list .rec__lead { align-self: start; }
  .p09-list .rec__value { text-align: start; justify-self: start; }
  .p09-val { display: flex; justify-content: flex-start; align-items: center; gap: var(--s-1); }
  .p09-date { text-align: start; margin-inline-end: var(--s-1); }
  .p09-list .rec--sub { margin-inline-start: var(--s-3); }
  .p09-slot { display: none; }
  .p09-hov { position: static; }
  .p09-tip-r, .p09-tip-l { top: 100%; }
}
@media (max-width: 21.25rem) {
  .p09-list .rec { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "lead body" "lead value" "actions actions"; }
}

.p09-q { flex: 1; min-width: 0; margin: 0; padding-top: var(--s-1); font-size: var(--fs-body); line-height: var(--lh-body); overflow-wrap: anywhere; }
.p09-muted { color: var(--text-2); }
.p09-fine { padding: 0 var(--s-4) var(--s-4); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--text-2); }
.p09-fine strong { color: var(--ink); }
.p09-fine > div + div { margin-top: var(--s-1); }
.p09-ph { color: var(--placeholder); }
.p09-m__sub { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); overflow-wrap: anywhere; }
.p09-all { display: flex; gap: var(--s-2); }
.p09-all .btn { flex: 1 1 0; }
.p09-foot-cnt { align-items: center; justify-content: space-between; }
.p09-foot-cnt > * { flex: 0 1 auto; min-width: 0; }
.p09-count { font-size: var(--fs-small); line-height: var(--lh-small); }
.p09-foot-one { justify-content: flex-end; }
.p09-foot-one > * { flex: 0 1 auto; min-width: 8rem; }
.p09-m { display: grid; gap: var(--s-2); }
.p09-m__name { font-weight: var(--fw-bold); font-size: var(--fs-body); line-height: var(--lh-small); overflow-wrap: anywhere; }
.p09-m__btns { display: flex; gap: var(--s-2); }
.p09-m__btns .btn { flex: 1 1 0; }
.p09-focus { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.p09-tipwrap { display: flex; justify-content: flex-end; padding: 0 var(--s-4) var(--s-3); margin-top: calc(var(--s-3) * -1); }
.p09-err { padding: 0 var(--s-4); }
.p09-err .banner { width: 100%; }
.p09-sel { color: var(--muted); }
.dialog .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p09-scrollbody { overflow: auto; }

.p09-opts { display: grid; gap: var(--s-2); min-width: 0; margin: 0; padding: 0; border: 0; }
.p09-opts > legend { width: 100%; padding: 0; margin-bottom: var(--s-1); }
.p09-opt.check { display: flex; align-items: center; gap: var(--s-3); width: 100%; min-height: var(--hit); padding: var(--s-1) var(--s-3); font-size: var(--fs-body); line-height: var(--lh-small); }
.p09-opt .check__label { min-width: 0; overflow-wrap: anywhere; }
.p09-opt.is-sel .check__label { color: var(--blue); font-weight: var(--fw-bold); }
.p09-opt input:disabled ~ .check__label { color: var(--c-disabled-text); font-weight: var(--fw-regular); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
.p09-m__btns .btn[aria-pressed="true"] { font-weight: var(--fw-bold); }
.p08-e { --frame-w: var(--w2); }
.p08-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p08-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) 0; }
.p08-err .banner { width: 100%; }
.p08-top { display: grid; gap: var(--s-2); }
.p08-top:empty { display: none; }
.p08-btnwrap { position: relative; display: inline-block; }
.p08-tip { position: absolute; z-index: 30; width: max-content; max-width: 17.5rem; }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p08-expl { flex: 1; display: grid; gap: var(--s-1); max-width: var(--measure); }

.content.p08-page { padding: var(--s-3); min-height: 100%; display: flex; flex-direction: column; gap: var(--s-3); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .content.p08-page { padding: var(--s-4) var(--s-5); } }
.p08-col { display: grid; gap: var(--s-4); width: 100%; max-width: 40rem; margin-inline: auto; align-content: start; }
.p08-head { display: grid; gap: var(--s-1); }
.p08-sub { overflow-wrap: anywhere; }
.p08-foot { position: sticky; bottom: 0; z-index: 1; display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-3); margin: auto calc(var(--s-3) * -1) calc(var(--s-3) * -1); padding: var(--s-3); background: var(--white); border-top: var(--w1) solid var(--rule); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p08-foot { margin: auto calc(var(--s-5) * -1) calc(var(--s-4) * -1); padding: var(--s-3) var(--s-5); } }
.p08-foot > .p08-foot-in { margin: 0 auto; }
.p08-foot-in { display: flex; flex-wrap: nowrap; gap: var(--s-2); width: 100%; max-width: 40rem; }
.p08-foot-in .btn { flex: 0 1 auto; }
.p08-foot-in .btn--primary { flex: 1 1 auto; }
.p08-foot-in .btn--danger { margin-inline-start: var(--s-2); }
@media (max-width: 24rem) { .p08-foot-in { flex-wrap: wrap; } .p08-foot-in .btn--danger { margin-inline-start: 0; flex: 1 1 100%; } }
.textarea.p08-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.textarea.p08-desc { min-height: calc(var(--ctl-h) * 4); padding-bottom: 1.75rem; resize: none; }
.textarea.p08-hascount { padding-bottom: 1.75rem; }
.p08-area { position: relative; }
.p08-count { position: absolute; right: var(--s-3); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; }
.p08-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p08-focus, .textarea.p08-focus, .input.p08-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p08-row2 { display: grid; grid-template-columns: minmax(0, 18rem) minmax(0, 1fr); gap: var(--s-3); align-items: start; }
@media (max-width: 38rem) { .p08-row2 { grid-template-columns: minmax(0, 1fr); } }
.p08-wrap { position: relative; display: grid; gap: var(--s-1); }
.p08-date { display: flex; align-items: center; gap: var(--s-2); }
.p08-date .input { flex: 1 1 auto; min-width: 0; max-width: 11rem; }
.p08-menu { position: absolute; z-index: 20; left: 0; right: 0; top: calc(100% + var(--s-1)); max-height: 15rem; overflow: auto; }
.p08-sec { padding: var(--s-1) var(--s-3) 0; font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-bold); color: var(--muted); }
.select[disabled], .select[aria-disabled="true"] { border-color: var(--c-disabled-border); color: var(--c-disabled-text); cursor: not-allowed; }
.p08-cal { position: absolute; z-index: 20; left: 0; top: calc(100% + var(--s-1)); width: min(19rem, 100%); min-width: 17rem; padding: var(--s-2); }
.p08-cal__head { display: flex; align-items: center; justify-content: space-between; gap: var(--s-2); }
.p08-cal__title { font-weight: var(--fw-bold); font-size: var(--fs-small); }
.p08-cal__grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--w2); text-align: center; }
.p08-cal__dow { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); padding: var(--s-1) 0; }
.p08-cal__day { min-height: var(--hit); padding: 0; border: var(--w1) solid transparent; border-radius: var(--r); background: transparent; font-size: var(--fs-small); font-variant-numeric: tabular-nums; }
.p08-cal__day[aria-selected="true"] { border: var(--w2) solid var(--blue); color: var(--blue); font-weight: var(--fw-bold); }
.p08-cal__day[disabled] { visibility: hidden; }
.p08-note { padding: var(--s-6) var(--s-3); display: grid; justify-items: center; gap: var(--s-3); }
.p08-added { color: var(--text-2); }
